-- Зимние вопросы: три существующие статьи. применение.
-- Идентификаторы живой базы на 15.11.2026:
--   33 adygeya-v-dekabre
--   14 lago-naki-zimoy-na-mashine
--   15 pervyy-sneg-na-lago-naki-ehat-ili-net
-- Повторный запуск ничего не меняет. Если текст статьи уже не совпадает
-- ни со снимком, ни с целевой версией, скрипт падает и не перезаписывает строку.
-- Не меняет slug, cover_url, district, is_published, featured_trail_ids.
-- Не трогает другие статьи, маршруты и места. Маршрут 11 и место 50
-- сверяются по хешу до и после. Не запускать scripts/seo_content_publish.py --live:
-- тот скрипт переписывает весь ноябрьский пакет, а не эти три строки.
-- Базу из облака не трогали: скрипт только для исполнителя на своей стороне.

BEGIN;

CREATE TEMP TABLE winter_intent_guard_articles AS
SELECT id, md5(convert_to(coalesce(body, ''), 'UTF8')) AS body_md5
FROM articles
WHERE id NOT IN (14, 15, 33);

CREATE TEMP TABLE winter_intent_guard_frozen AS
SELECT 'trail-11'::text AS k,
       md5(convert_to(coalesce(name, '') || '|' || coalesce(description, ''), 'UTF8')) AS h
FROM trails WHERE id = 11
UNION ALL
SELECT 'place-50'::text,
       md5(convert_to(coalesce(name, '') || '|' || coalesce(description, ''), 'UTF8'))
FROM checkpoints WHERE id = 50;

DO $migrate$
DECLARE
  v_title text;
  v_excerpt text;
  v_body text;
  v_faq jsonb;
  v_feat integer[];
  v_cover text;
  v_slug text;
  v_pub boolean;
  v_trails integer[];
  v_n int;
  v_articles int;
BEGIN
  SELECT count(*) INTO v_articles FROM articles;
  IF (SELECT count(*) FROM winter_intent_guard_frozen) <> 2 THEN
    RAISE EXCEPTION 'precheck: нет маршрута 11 или места 50';
  END IF;
  IF (SELECT count(*) FROM articles WHERE id IN (14, 15, 33)) <> 3 THEN
    RAISE EXCEPTION 'precheck: среди статей 14, 15 и 33 кого-то нет';
  END IF;

  -- article 33 adygeya-v-dekabre
  SELECT title, excerpt, body, faq, featured_checkpoint_ids, cover_url, slug, is_published, featured_trail_ids
    INTO v_title, v_excerpt, v_body, v_faq, v_feat, v_cover, v_slug, v_pub, v_trails
  FROM articles WHERE id = 33 FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'article 33 (adygeya-v-dekabre) не найден';
  END IF;
  IF v_slug IS DISTINCT FROM 'adygeya-v-dekabre' OR v_pub IS DISTINCT FROM TRUE THEN
    RAISE EXCEPTION 'article 33: slug или is_published не те, что в снимке';
  END IF;
  IF v_title = $a33ft2$Стоит ли ехать в Адыгею в декабре$a33ft2$
     AND v_excerpt IS NOT DISTINCT FROM $a33fe2$В декабре Адыгея подходит для тихих дней в долине и коротких прогулок, но не для гарантированного снега внизу. Погода Майкопа и плато разная, световой день короткий, а каникулы — отдельная поездка.$a33fe2$
     AND v_body = $a33fb2$<p><strong>Да — если тебе нужна тихая долина и короткие прогулки. Нет — если без снега наверху или без длинного трека ехать незачем.</strong> Декабрь в Адыгее не горнолыжный отпуск и не обещание белых улиц в Майкопе. Каникулы — другая поездка: про них есть отдельная статья, а цен на жильё и билеты здесь нет.</p>
<p>Снег, проезд к КПП и то, чем заняться внизу, — три разных вопроса. Ниже у каждого свой короткий ответ.</p>
<h2>Кому поездка в декабре подходит?</h2>
<p><strong>Тем, кто готов к сырой долине, льду на ступенях и возвращению засветло.</strong> Не тем, кто хочет гарантированный снег внизу, многодневный поход или день «как на Красной Поляне»: горнолыжных трасс на Лаго-Наки нет.</p>
<h3>Что в такой поездке получается?</h3>
<p><strong>Тихие дни до каникул и один-два коротких выхода, даже если на плато в этот раз снега не будет.</strong> График с утра до темноты из декабря не собирается. Если движение наверх ограничат, день всё равно есть чем занять внизу. Машине выше Даховской нужны зимние шины: что именно запрещает закон и чего он не обещает, написано в статье про дорогу, здесь это не допуск наверх.</p>
<h3>Кому лучше выбрать другой месяц?</h3>
<p><strong>Тем, кому нужен снег внизу, длинный трек или длинный световой день.</strong> Устойчивый снег именно в Майкопе или в Каменномостском декабрь не обещает. <a href="/mesta/56">Каменное море</a>, <a href="/mesta/61">Оштен</a> и <a href="/mesta/66">приют Фишт</a> в декабре не планируем.</p>
<h2>Чем погода внизу отличается от погоды наверху?</h2>
<p><strong>По одному прогнозу для Майкопа нельзя понять, что на плато.</strong> Это разные высоты, и одной «погоды Адыгеи» из них не получается.</p>
<p>Для Майкопа есть климатическая норма, не прогноз на декабрь 2026 года. В таблице «Климат городов России» (период осреднения 1961–1990) у декабря средний дневной максимум около +6,9 °C и средний ночной минимум около −1,3 °C — <a href="https://pogoda.meteoinfo.ru/categ-articles/15-climate-cat/klimaticheskie-normy/clim-towns?start=40" rel="nofollow noopener" target="_blank">таблица Гидрометцентра</a>. Норма старая: конкретная неделя бывает и теплее, и холоднее. Такой же таблицы для Каменномостского и для КПП «Лагонаки» в этом тексте нет, поэтому градусы «на сколько холоднее наверху» мы не выдумываем.</p>
<p>Практический вывод короткий. В долине декабрь чаще сырой, ночью температура уходит к нулю и ниже, утром на ступенях лёд. Выше по дороге на <a href="/mesta/55">плато Лаго-Наки</a> в тот же день снег может лежать, а может уже сойти. Перед выездом смотри прогноз отдельно для долины и для плато.</p>
<h2>Есть ли в декабре снег?</h2>
<p><strong>Наверху он бывает, в Майкопе устойчивым его считать нельзя, и ни то ни другое не расписание на твои даты.</strong> Первый снег на плато и покров, который долежит до января, — не одно и то же: тонкий слой после потепления сходит.</p>
<p>Фразу «в декабре на Лаго-Наки уже зима» как обещание мы не используем. Как отличить сезон от сводки на сегодня — в статье <a href="/stati/pervyy-sneg-na-lago-naki-ehat-ili-net">«Есть ли снег на Лаго-Наки»</a>. Эта страница сама снег «на сейчас» не публикует и каждый день не обновляется.</p>
<figure class="shot"><img src="https://hiotbrjgilwlztlfdkmg.supabase.co/storage/v1/object/public/uploads/df05967e489c41dcab62a3750982ecfa.webp" alt="Плато Лаго-Наки зимой: наверху снег, когда в долине его ещё нет" loading="lazy"><figcaption>Плато Лаго-Наки зимой: наверху снег, когда в долине его ещё нет<br><small>Фото: RusRec13, <a href="https://creativecommons.org/licenses/by-sa/3.0" rel="nofollow noopener" target="_blank">CC BY-SA 3.0</a>, <a href="https://commons.wikimedia.org/wiki/File:Panorama_plato_L-N.jpg" rel="nofollow noopener" target="_blank">Wikimedia Commons</a></small></figcaption></figure>
<p>Кадр — снежный день на плато, а не справка, что так будет в твою неделю.</p>
<h2>Что смотреть, если на плато не ехать?</h2>
<p><strong>Долину Белой и Гузерипль.</strong> Это зимний день без высокогорья, а не запасной снег и не список «всё точно открыто».</p>
<ul>
<li><a href="/mesta/24">Хаджохская теснина</a> и <a href="/mesta/40">водопады Руфабго</a> работают круглый год, но после ночного минуса ступени и мостки скользкие. Длинную тропу ставь на первую половину дня: вне лета касса может закрыться раньше. Официальные часы и цены здесь не подтверждаем — они с оговорками лежат в карточках и в разборе <a href="/stati/kamennomostskiy-hadzhoh-zimoy">«Каменномостский зимой»</a>.</li>
<li><a href="/mesta/62">Музей природы</a> и <a href="/mesta/63">вольеры</a> в Гузерипле — короткий вариант под крышей и рядом с ней, если дорога до посёлка нормальная. Подробнее — <a href="/stati/guzeripl-zimoy">«Гузерипль зимой»</a>.</li>
<li><a href="/mesta/52">Гранитный каньон</a> смотри со смотровой у дороги, без спуска к воде в гололёд.</li>
<li><a href="/mesta/25">Большая Азишская пещера</a> внутри от дождя не зависит, но это Краснодарский край и горная дорога. Имеет смысл только вместе с решением по проезду, не как идея «развернёмся уже на серпантине».</li>
</ul>
<h2>Как уложить день в короткий свет?</h2>
<p><strong>Горную часть заканчивай засветло.</strong> «Ещё одна точка после четырёх» в декабре часто означает спуск в темноте.</p>
<p>Для Майкопа таблица «Моего города» (широта 44,605, долгота 40,105, пояс +3) на 30 ноября 2026 года даёт заход солнца в 16:41 и конец гражданских сумерек в 17:14. В декабре у солнцестояния день короче, а не длиннее. Минуту на свою дату смотри в <a href="http://www.mojgorod.ru/cgi-bin/moonsun.cgi?OKATO=79401" rel="nofollow noopener" target="_blank">той же таблице</a>: она показывает ближайшие недели, не весь год вперёд. В ущелье темнеет раньше, чем на открытом месте в городе.</p>
<p>Рабочая схема выходных: в субботу один главный выход утром — Руфабго или теснина, не оба «до темноты». Воскресенье — плато, только если дорога и шины позволяют, иначе Гузерипль и каньон. Готовый каркас — <a href="/stati/adygeya-zimoy-na-2-dnya">«Адыгея зимой на 2 дня»</a>.</p>
<h2>Чем начало декабря отличается от каникул?</h2>
<p><strong>Это разные поездки, и цены мы здесь не сравниваем.</strong> Новогодние каникулы 2026/27 разобраны отдельно: <a href="/stati/novyy-god-v-adygee">«Новый год в Адыгее 2027»</a>. Даты постановления и размер «праздничной наценки» с этой страницы не повторяем: своего прайса у нас нет.</p>
<p>До каникул проще собрать тихий день в долине. Праздничную неделю не описываем как продолжение того же декабря: людей больше, а день на плато чаще упирается в снегопад и в ограничения движения. Это не прогноз загруженности на конкретное число.</p>
<p>Дальше у каждой страницы своя задача: <a href="/stati/lago-naki-zimoy-na-mashine">как доехать до Лаго-Наки зимой</a>, <a href="/stati/pervyy-sneg-na-lago-naki-ehat-ili-net">есть ли снег</a>, <a href="/stati/adygeya-v-noyabre">чем ноябрь отличался</a>, общий выбор сезона — <a href="/kuda/zimoy">Адыгея зимой</a>.</p>
<p class="photo-credit"><small>Фото на обложке: Dash.rubleva, <a href="https://creativecommons.org/licenses/by-sa/4.0" rel="nofollow noopener" target="_blank">CC BY-SA 4.0</a>, <a href="https://commons.wikimedia.org/wiki/File:%D0%9F%D0%BB%D0%B0%D1%82%D0%BE_%D0%9B%D0%B0%D0%B3%D0%BE-%D0%9D%D0%B0%D0%BA%D0%B8_%D0%B2%D0%B8%D0%B4_%D1%81%D0%BE_%D1%81%D0%BA%D0%B0%D0%BB%D1%8B_02.jpg" rel="nofollow noopener" target="_blank">Wikimedia Commons</a></small></p>$a33fb2$
     AND v_faq = $faq$[{"question":"Стоит ли ехать в Адыгею в декабре?","answer":"Да, если нужны тихие дни в долине и короткие прогулки и ты не ждёшь снега в Майкопе или длинного трека. Нет, если без снега на плато поездка теряет смысл."},{"question":"Какая погода в Адыгее в декабре?","answer":"Для Майкопа климатическая норма 1961–1990 годов: днём около +6,9 °C, ночью около −1,3 °C. Это не прогноз. Погоду плато смотри отдельно."},{"question":"Есть ли снег в Адыгее в декабре?","answer":"В Майкопе устойчивый снег нормой не является. Выше по дороге на Лаго-Наки он бывает, но день ото дня разный. Как отличить сезон от сводки на сегодня — в статье про снег."},{"question":"Что посмотреть, если на плато не подняться?","answer":"Хаджохскую теснину, Руфабго, если тропа не в наледи, музей и вольеры в Гузерипле, смотровые Гранитного каньона. Летние маршруты заповедника не планируй."}]$faq$::jsonb
     AND v_feat = ARRAY[24,40,62,55]::integer[] THEN
    NULL; -- уже в целевом состоянии
  ELSIF v_title = $a33ft1$Адыгея в декабре: погода, снег и интересные места$a33ft1$
     AND v_excerpt IS NOT DISTINCT FROM $a33fe1$Адыгея в декабре: погода в Майкопе и на плато, что работает до праздников, где первый снег и почему начало декабря — самое тихое время для поездки.$a33fe1$
     AND v_body = $a33fb1$<p>Декабрь — самый недооценённый месяц для Адыгеи. До 25-го здесь тихо и спокойно, жильё дешевле праздничного, а на плато уже бывает снег. Но декабрь — это и самые короткие дни: <strong>темнеет около 17:00</strong>, поэтому план строим на 7–8 светлых часов.</p>
<h2>Погода в декабре</h2>
<ul>
<li>Майкоп и равнина: днём обычно +6…+8, ночью около нуля, чаще сыро, чем снежно.</li>
<li>Каменномостский (около 400 м): днём в среднем около +5, ночью −3…−5, утром на ступенях бывает гололёд.</li>
<li><a href="/mesta/55">Плато Лаго-Наки</a> (КПП 1780 м): здесь уже зима — снег обычно ложится в декабре, но в тёплые годы позже. Разница с Майкопом бывает 10–15 градусов.</li>
</ul>
<p>Прогноз смотри отдельно для долины и для плато — по одному Майкопу не понять, что будет наверху.</p>
<h2>Что открыто</h2>
<p>Всё, что работает круглый год: <a href="/mesta/24">Хаджохская теснина</a>, <a href="/mesta/40">Руфабго</a>, <a href="/mesta/62">музей природы</a> и <a href="/mesta/63">вольеры</a> в Гузерипле, термы под Майкопом, <a href="/mesta/25">Азишская пещера</a> (Краснодарский край, только с экскурсией). Летние места — <a href="/mesta/56">Каменное море</a>, <a href="/mesta/61">Оштен</a>, <a href="/mesta/66">приют Фишт</a> — в декабре не планируем.</p>
<figure class="shot"><img src="https://hiotbrjgilwlztlfdkmg.supabase.co/storage/v1/object/public/uploads/df05967e489c41dcab62a3750982ecfa.webp" alt="Плато Лаго-Наки зимой: наверху снег, когда в долине его ещё нет" loading="lazy"><figcaption>Плато Лаго-Наки зимой: наверху снег, когда в долине его ещё нет<br><small>Фото: RusRec13, <a href="https://creativecommons.org/licenses/by-sa/3.0" rel="nofollow noopener" target="_blank">CC BY-SA 3.0</a>, <a href="https://commons.wikimedia.org/wiki/File:Panorama_plato_L-N.jpg" rel="nofollow noopener" target="_blank">Wikimedia Commons</a></small></figcaption></figure>
<h2>Первый снег на Лаго-Наки</h2>
<p>Если хочется снега, ехать стоит после устойчивого похолодания, а не сразу после первого снегопада: в первые дни верх дороги бывает не расчищен. Как понять, пора или нет, — в статье <a href="/stati/pervyy-sneg-na-lago-naki-ehat-ili-net">«Первый снег на Лаго-Наки: ехать или нет»</a>. Зимние шины в декабре обязательны.</p>
<h2>Стоит ли ехать в декабре</h2>
<p>Да, если тебе нужны тишина, термы и пара прогулок по ущельям. Нет, если ждёшь гарантированного снега внизу или длинных треккингов. Лучшее окно — <strong>первые три недели декабря</strong>: с 31-го начинаются каникулы (до 10 января), и цены вместе с людьми резко растут — про праздники отдельно: <a href="/stati/novyy-god-v-adygee">Новый год в Адыгее 2027</a>.</p>
<h2>План на декабрьские выходные</h2>
<ol>
<li>Суббота: Руфабго до 13:00, теснина после обеда, вечером термы.</li>
<li>Воскресенье: если на плато снег и дорога чистая — утро у КПП «Лагонаки»; если нет — Гузерипль и <a href="/mesta/52">Гранитный каньон</a>.</li>
</ol>
<p>Готовая версия — <a href="/stati/adygeya-zimoy-na-2-dnya">Адыгея зимой на 2 дня</a>. Что было месяцем раньше — <a href="/stati/adygeya-v-noyabre">Адыгея в ноябре</a>. Всё про сезон — <a href="/kuda/zimoy">Адыгея зимой</a>.</p>
<p class="photo-credit"><small>Фото на обложке: Dash.rubleva, <a href="https://creativecommons.org/licenses/by-sa/4.0" rel="nofollow noopener" target="_blank">CC BY-SA 4.0</a>, <a href="https://commons.wikimedia.org/wiki/File:%D0%9F%D0%BB%D0%B0%D1%82%D0%BE_%D0%9B%D0%B0%D0%B3%D0%BE-%D0%9D%D0%B0%D0%BA%D0%B8_%D0%B2%D0%B8%D0%B4_%D1%81%D0%BE_%D1%81%D0%BA%D0%B0%D0%BB%D1%8B_02.jpg" rel="nofollow noopener" target="_blank">Wikimedia Commons</a></small></p>$a33fb1$
     AND v_faq = $faq$[{"answer":"В Майкопе днём обычно +6…+8, ночью около нуля. На плато Лаго-Наки уже зима и чаще всего лежит снег.","question":"Какая погода в Адыгее в декабре?"},{"answer":"Внизу — редко и ненадолго. На Лаго-Наки снег обычно ложится в декабре, но в тёплые годы позже.","question":"Есть ли снег в Адыгее в декабре?"},{"answer":"Хаджохская теснина, водопады Руфабго, экоцентр в Гузерипле, термы под Майкопом и Азишская пещера. Летние маршруты закрыты.","question":"Что открыто в Адыгее в декабре?"},{"answer":"Да, если хочется тишины, терм и коротких прогулок. Лучшее время — до 25 декабря: потом начинаются каникулы и цены растут.","question":"Стоит ли ехать в Адыгею в декабре?"}]$faq$::jsonb
     AND v_feat = ARRAY[24,55,62,67]::integer[] THEN
    UPDATE articles
       SET title = $a33ft3$Стоит ли ехать в Адыгею в декабре$a33ft3$,
           excerpt = $a33fe3$В декабре Адыгея подходит для тихих дней в долине и коротких прогулок, но не для гарантированного снега внизу. Погода Майкопа и плато разная, световой день короткий, а каникулы — отдельная поездка.$a33fe3$,
           body = $a33fb3$<p><strong>Да — если тебе нужна тихая долина и короткие прогулки. Нет — если без снега наверху или без длинного трека ехать незачем.</strong> Декабрь в Адыгее не горнолыжный отпуск и не обещание белых улиц в Майкопе. Каникулы — другая поездка: про них есть отдельная статья, а цен на жильё и билеты здесь нет.</p>
<p>Снег, проезд к КПП и то, чем заняться внизу, — три разных вопроса. Ниже у каждого свой короткий ответ.</p>
<h2>Кому поездка в декабре подходит?</h2>
<p><strong>Тем, кто готов к сырой долине, льду на ступенях и возвращению засветло.</strong> Не тем, кто хочет гарантированный снег внизу, многодневный поход или день «как на Красной Поляне»: горнолыжных трасс на Лаго-Наки нет.</p>
<h3>Что в такой поездке получается?</h3>
<p><strong>Тихие дни до каникул и один-два коротких выхода, даже если на плато в этот раз снега не будет.</strong> График с утра до темноты из декабря не собирается. Если движение наверх ограничат, день всё равно есть чем занять внизу. Машине выше Даховской нужны зимние шины: что именно запрещает закон и чего он не обещает, написано в статье про дорогу, здесь это не допуск наверх.</p>
<h3>Кому лучше выбрать другой месяц?</h3>
<p><strong>Тем, кому нужен снег внизу, длинный трек или длинный световой день.</strong> Устойчивый снег именно в Майкопе или в Каменномостском декабрь не обещает. <a href="/mesta/56">Каменное море</a>, <a href="/mesta/61">Оштен</a> и <a href="/mesta/66">приют Фишт</a> в декабре не планируем.</p>
<h2>Чем погода внизу отличается от погоды наверху?</h2>
<p><strong>По одному прогнозу для Майкопа нельзя понять, что на плато.</strong> Это разные высоты, и одной «погоды Адыгеи» из них не получается.</p>
<p>Для Майкопа есть климатическая норма, не прогноз на декабрь 2026 года. В таблице «Климат городов России» (период осреднения 1961–1990) у декабря средний дневной максимум около +6,9 °C и средний ночной минимум около −1,3 °C — <a href="https://pogoda.meteoinfo.ru/categ-articles/15-climate-cat/klimaticheskie-normy/clim-towns?start=40" rel="nofollow noopener" target="_blank">таблица Гидрометцентра</a>. Норма старая: конкретная неделя бывает и теплее, и холоднее. Такой же таблицы для Каменномостского и для КПП «Лагонаки» в этом тексте нет, поэтому градусы «на сколько холоднее наверху» мы не выдумываем.</p>
<p>Практический вывод короткий. В долине декабрь чаще сырой, ночью температура уходит к нулю и ниже, утром на ступенях лёд. Выше по дороге на <a href="/mesta/55">плато Лаго-Наки</a> в тот же день снег может лежать, а может уже сойти. Перед выездом смотри прогноз отдельно для долины и для плато.</p>
<h2>Есть ли в декабре снег?</h2>
<p><strong>Наверху он бывает, в Майкопе устойчивым его считать нельзя, и ни то ни другое не расписание на твои даты.</strong> Первый снег на плато и покров, который долежит до января, — не одно и то же: тонкий слой после потепления сходит.</p>
<p>Фразу «в декабре на Лаго-Наки уже зима» как обещание мы не используем. Как отличить сезон от сводки на сегодня — в статье <a href="/stati/pervyy-sneg-na-lago-naki-ehat-ili-net">«Есть ли снег на Лаго-Наки»</a>. Эта страница сама снег «на сейчас» не публикует и каждый день не обновляется.</p>
<figure class="shot"><img src="https://hiotbrjgilwlztlfdkmg.supabase.co/storage/v1/object/public/uploads/df05967e489c41dcab62a3750982ecfa.webp" alt="Плато Лаго-Наки зимой: наверху снег, когда в долине его ещё нет" loading="lazy"><figcaption>Плато Лаго-Наки зимой: наверху снег, когда в долине его ещё нет<br><small>Фото: RusRec13, <a href="https://creativecommons.org/licenses/by-sa/3.0" rel="nofollow noopener" target="_blank">CC BY-SA 3.0</a>, <a href="https://commons.wikimedia.org/wiki/File:Panorama_plato_L-N.jpg" rel="nofollow noopener" target="_blank">Wikimedia Commons</a></small></figcaption></figure>
<p>Кадр — снежный день на плато, а не справка, что так будет в твою неделю.</p>
<h2>Что смотреть, если на плато не ехать?</h2>
<p><strong>Долину Белой и Гузерипль.</strong> Это зимний день без высокогорья, а не запасной снег и не список «всё точно открыто».</p>
<ul>
<li><a href="/mesta/24">Хаджохская теснина</a> и <a href="/mesta/40">водопады Руфабго</a> работают круглый год, но после ночного минуса ступени и мостки скользкие. Длинную тропу ставь на первую половину дня: вне лета касса может закрыться раньше. Официальные часы и цены здесь не подтверждаем — они с оговорками лежат в карточках и в разборе <a href="/stati/kamennomostskiy-hadzhoh-zimoy">«Каменномостский зимой»</a>.</li>
<li><a href="/mesta/62">Музей природы</a> и <a href="/mesta/63">вольеры</a> в Гузерипле — короткий вариант под крышей и рядом с ней, если дорога до посёлка нормальная. Подробнее — <a href="/stati/guzeripl-zimoy">«Гузерипль зимой»</a>.</li>
<li><a href="/mesta/52">Гранитный каньон</a> смотри со смотровой у дороги, без спуска к воде в гололёд.</li>
<li><a href="/mesta/25">Большая Азишская пещера</a> внутри от дождя не зависит, но это Краснодарский край и горная дорога. Имеет смысл только вместе с решением по проезду, не как идея «развернёмся уже на серпантине».</li>
</ul>
<h2>Как уложить день в короткий свет?</h2>
<p><strong>Горную часть заканчивай засветло.</strong> «Ещё одна точка после четырёх» в декабре часто означает спуск в темноте.</p>
<p>Для Майкопа таблица «Моего города» (широта 44,605, долгота 40,105, пояс +3) на 30 ноября 2026 года даёт заход солнца в 16:41 и конец гражданских сумерек в 17:14. В декабре у солнцестояния день короче, а не длиннее. Минуту на свою дату смотри в <a href="http://www.mojgorod.ru/cgi-bin/moonsun.cgi?OKATO=79401" rel="nofollow noopener" target="_blank">той же таблице</a>: она показывает ближайшие недели, не весь год вперёд. В ущелье темнеет раньше, чем на открытом месте в городе.</p>
<p>Рабочая схема выходных: в субботу один главный выход утром — Руфабго или теснина, не оба «до темноты». Воскресенье — плато, только если дорога и шины позволяют, иначе Гузерипль и каньон. Готовый каркас — <a href="/stati/adygeya-zimoy-na-2-dnya">«Адыгея зимой на 2 дня»</a>.</p>
<h2>Чем начало декабря отличается от каникул?</h2>
<p><strong>Это разные поездки, и цены мы здесь не сравниваем.</strong> Новогодние каникулы 2026/27 разобраны отдельно: <a href="/stati/novyy-god-v-adygee">«Новый год в Адыгее 2027»</a>. Даты постановления и размер «праздничной наценки» с этой страницы не повторяем: своего прайса у нас нет.</p>
<p>До каникул проще собрать тихий день в долине. Праздничную неделю не описываем как продолжение того же декабря: людей больше, а день на плато чаще упирается в снегопад и в ограничения движения. Это не прогноз загруженности на конкретное число.</p>
<p>Дальше у каждой страницы своя задача: <a href="/stati/lago-naki-zimoy-na-mashine">как доехать до Лаго-Наки зимой</a>, <a href="/stati/pervyy-sneg-na-lago-naki-ehat-ili-net">есть ли снег</a>, <a href="/stati/adygeya-v-noyabre">чем ноябрь отличался</a>, общий выбор сезона — <a href="/kuda/zimoy">Адыгея зимой</a>.</p>
<p class="photo-credit"><small>Фото на обложке: Dash.rubleva, <a href="https://creativecommons.org/licenses/by-sa/4.0" rel="nofollow noopener" target="_blank">CC BY-SA 4.0</a>, <a href="https://commons.wikimedia.org/wiki/File:%D0%9F%D0%BB%D0%B0%D1%82%D0%BE_%D0%9B%D0%B0%D0%B3%D0%BE-%D0%9D%D0%B0%D0%BA%D0%B8_%D0%B2%D0%B8%D0%B4_%D1%81%D0%BE_%D1%81%D0%BA%D0%B0%D0%BB%D1%8B_02.jpg" rel="nofollow noopener" target="_blank">Wikimedia Commons</a></small></p>$a33fb3$,
           faq = $faq$[{"question":"Стоит ли ехать в Адыгею в декабре?","answer":"Да, если нужны тихие дни в долине и короткие прогулки и ты не ждёшь снега в Майкопе или длинного трека. Нет, если без снега на плато поездка теряет смысл."},{"question":"Какая погода в Адыгее в декабре?","answer":"Для Майкопа климатическая норма 1961–1990 годов: днём около +6,9 °C, ночью около −1,3 °C. Это не прогноз. Погоду плато смотри отдельно."},{"question":"Есть ли снег в Адыгее в декабре?","answer":"В Майкопе устойчивый снег нормой не является. Выше по дороге на Лаго-Наки он бывает, но день ото дня разный. Как отличить сезон от сводки на сегодня — в статье про снег."},{"question":"Что посмотреть, если на плато не подняться?","answer":"Хаджохскую теснину, Руфабго, если тропа не в наледи, музей и вольеры в Гузерипле, смотровые Гранитного каньона. Летние маршруты заповедника не планируй."}]$faq$::jsonb,
           featured_checkpoint_ids = ARRAY[24,40,62,55]::integer[],
           updated_at = now()
     WHERE id = 33
       AND slug = 'adygeya-v-dekabre'
       AND is_published IS TRUE;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    IF v_n <> 1 THEN
      RAISE EXCEPTION 'article 33: обновлена не одна строка (%)', v_n;
    END IF;
  ELSE
    RAISE EXCEPTION 'article 33 (adygeya-v-dekabre) не совпал ни со снимком «до», ни с целевым текстом — строку не трогаем';
  END IF;
  IF (SELECT cover_url FROM articles WHERE id = 33) IS DISTINCT FROM v_cover
     OR (SELECT slug FROM articles WHERE id = 33) IS DISTINCT FROM 'adygeya-v-dekabre'
     OR (SELECT is_published FROM articles WHERE id = 33) IS DISTINCT FROM TRUE
     OR (SELECT featured_trail_ids FROM articles WHERE id = 33) IS DISTINCT FROM v_trails
     OR (SELECT position('Кому поездка в декабре подходит?' IN body) FROM articles WHERE id = 33) = 0 THEN
    RAISE EXCEPTION 'article 33: после шага съехали обложка, адрес, публикация или текст';
  END IF;


  -- article 14 lago-naki-zimoy-na-mashine
  SELECT title, excerpt, body, faq, featured_checkpoint_ids, cover_url, slug, is_published, featured_trail_ids
    INTO v_title, v_excerpt, v_body, v_faq, v_feat, v_cover, v_slug, v_pub, v_trails
  FROM articles WHERE id = 14 FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'article 14 (lago-naki-zimoy-na-mashine) не найден';
  END IF;
  IF v_slug IS DISTINCT FROM 'lago-naki-zimoy-na-mashine' OR v_pub IS DISTINCT FROM TRUE THEN
    RAISE EXCEPTION 'article 14: slug или is_published не те, что в снимке';
  END IF;
  IF v_title = $a14ft2$Как доехать до Лаго-Наки зимой$a14ft2$
     AND v_excerpt IS NOT DISTINCT FROM $a14fe2$До КПП «Лагонаки» зимой едут на машине со стороны Даховской, но асфальт не обещает проезд в конкретный день. Легковым машинам в декабре нужны зимние шины на всех колёсах; открыта ли дорога сегодня, смотри в сводках, не на этой странице.$a14fe2$
     AND v_body = $a14fb2$<p><strong>Зимой до КПП «Лагонаки» едут на машине со стороны Даховской. Доехать «в любой день и на любой резине» нельзя.</strong> Асфальт на этом направлении есть. Открыт ли он сегодня, эта страница не знает и проезд не гарантирует: решают шины, то, что лежит на покрытии, и нет ли ограничения движения.</p>
<p>Снег на хребте и проезд — разные новости. Про снег — <a href="/stati/pervyy-sneg-na-lago-naki-ehat-ili-net">отдельная страница</a>. Здесь только дорога.</p>
<h2>Как доехать до КПП зимой?</h2>
<p><strong>Обычный заезд — из долины через Даховскую, дальше серпантин в сторону КПП.</strong> Участок идёт и по Адыгее, и по Краснодарскому краю, поэтому фраза «дорогу на Лаго-Наки закрыли» без названия участка и без того, кто её опубликовал, ещё ничего не значит. <a href="/mesta/25">Большая Азишская пещера</a> административно в крае, не в Адыгее.</p>
<p>По мере набора высоты погода меняется: внизу дождь, выше снег или туман. Заправься в Каменномостском или в Даховской до начала подъёма. Скачай карту для работы без связи. Время, которое навигатор показал в сухую погоду, зимой не план.</p>
<h2>Какие шины требует закон и чего он не гарантирует?</h2>
<p><strong>В декабре, январе и феврале легковой машине нужны зимние шины на всех колёсах. Это запрет эксплуатации, а не обещание, что дорога будет проезжей.</strong></p>
<p>Пункт 5.2 Перечня неисправностей и условий, при которых запрещается эксплуатация транспортных средств (приложение к Основным положениям, постановление Правительства РФ от 23.10.1993 № 1090), называет два условия: на транспортном средстве категорий M1 и N1 не установлены зимние шины в зимний период (декабрь, январь, февраль); зимние шины установлены не на все колёса. Для обычной легковой машины это как раз этот пункт. Текст сверен по карточке <a href="https://www.consultant.ru/document/cons_doc_LAW_2709/ec034e2d80085428905b10189ee7d0d08173e8c7/" rel="nofollow noopener" target="_blank">КонсультантПлюс</a>, где у документа указана редакция от 28.08.2026. Сумму штрафа здесь не приводим.</p>
<p>Этого минимума мало для серпантина. Перечень не обещает, что зимняя шина проедет перемёт, колею или ледяную корку, и не обязывает держать участок открытым. Полный привод помогает тронуться в части условий, не заменяет шины и не сокращает тормозной путь на льду.</p>
<h3>Нужны ли цепи на легковой?</h3>
<p><strong>Пункт 5.2 для категории M1 цепи не требует.</strong> Цепи, если они подходят машине и ты умеешь их ставить, — снаряжение на конкретный участок. Они не заменяют зимние шины и не дают права ехать через закрытие. Отдельное требование возить цепи зимой в этом перечне относится к другим категориям транспорта, не к обычной легковушке.</p>
<p>Остаточная глубина протектора зимней шины — пункт 5.5 того же перечня: 4 мм и менее на обледеневшем или заснеженном покрытии. Выявляют это средствами диагностики, а не линейкой на обочине. Это не самопроверка перед шлагбаумом.</p>
<h2>Открыта ли дорога сегодня?</h2>
<p><strong>Текущего статуса здесь нет.</strong> Ограничение могут ввести утром и снять днём. Мы не пишем ни «сегодня открыто», ни «сегодня закрыто».</p>
<p>Пример, что так уже бывало, а не прогноз: 31 декабря 2025 года Госавтоинспекция Краснодарского края сообщала о временном ограничении движения на автодороге «станица Даховская — плато Лаго-Наки» из-за снега. Так это передал <a href="https://ria.ru/20251231/kuban-2065884978.html" rel="nofollow noopener" target="_blank">РИА Новости</a>. Это прошлый сезон. Когда ограничение сняли и сняли ли его в тот же вечер, здесь не утверждаем.</p>
<p>Перед выездом смотри сообщения по обоим регионам: дорога их пересекает. Раздел Краснодарского края — <a href="https://xn--90adear.xn--p1ai/r/23/" rel="nofollow noopener" target="_blank">гибдд.рф/r/23</a>, раздел Адыгеи — <a href="https://xn--90adear.xn--p1ai/r/01/" rel="nofollow noopener" target="_blank">гибдд.рф/r/01</a>. Статья эти страницы не зеркалирует. Если сайт не открылся, не заменяй его пересказом из чата. Ограничение на месте обозначают и экипажи: объезжать его по обочине нельзя.</p>
<h2>Чем дорога отличается от КПП и троп?</h2>
<p><strong>Доехать до шлагбаума, пройти КПП и идти по летней тропе — три разных разрешения.</strong></p>
<p>Дорога — это проезд в сторону <a href="/mesta/55">Лаго-Наки</a>. Её открывают и ограничивают по обстановке.</p>
<p>КПП — контроль Кавказского заповедника. Машина у шлагбаума не означает, что дальше можно идти: есть правила посещения и сезонный режим маршрутов.</p>
<p>По сообщению заповедника от 26 октября 2026 года, с 27 октября маршруты №30 В и Г закрыты, а №30 А и Б со стороны КПП «Лагонаки» оставлены для однодневного выхода до Инструкторской щели, без ночёвки. Это не справка на день поездки: более позднее объявление отменяет старое. Смотри <a href="https://www.kavkazzapoved.ru/" rel="nofollow noopener" target="_blank">kavkazzapoved.ru</a>. Летнее описание «тридцатки» — не зимний план к Фишту.</p>
<h2>Где можно остановиться по пути?</h2>
<p><strong>Отдельной проверенной схемы парковок мы не публикуем.</strong> Останавливайся только там, где это разрешено и машина не стоит в полосе. Зимой не выходи «на кадр», если подход не виден из-под снега или льда.</p>
<p>На дороге есть <a href="/mesta/39">смотровая с качелями</a>. Это не обязательная остановка: лёд на подходе важнее качелей.</p>
<figure class="shot"><img alt="Смотровая с качелями по дороге на Лаго-Наки" loading="lazy" src="https://hiotbrjgilwlztlfdkmg.supabase.co/storage/v1/object/public/uploads/542c3bb3b5e0432b9b225d659648e10d.webp"/><figcaption>Смотровая с качелями по дороге на Лаго-Наки</figcaption></figure>
<p><a href="/mesta/25">Большая Азишская пещера</a> тоже по пути. Имеет смысл, если и дорога, и подход безопасны и экскурсия в этот день идёт. Часы сами из того, что к пещере ведёт асфальт, не следуют — уточни на месте.</p>
<figure class="shot"><img alt="Большая Азишская пещера" loading="lazy" src="https://hiotbrjgilwlztlfdkmg.supabase.co/storage/v1/object/public/uploads/f6e131d6fccc471c9a4b3da7b9a8f39d.jpg"/><figcaption>Большая Азишская пещера</figcaption></figure>
<p>Не ставь зимой целью <a href="/mesta/56">Каменное море</a> или выход на <a href="/mesta/58">Утюг</a>. Край плато, наледь и ветер — не летняя прогулка по сухой тропе.</p>
<h2>Как быть без машины?</h2>
<p><strong>Подтверждённого рейса до КПП «Лагонаки» у нас нет.</strong> Автобусы до Каменномостского, Даховской и Гузерипля, о которых написано в других материалах сайта, сами по себе до плато не доезжают. Пока перевозчик не показал рейс на твой день, не закладывай Лаго-Наки в поездку без машины. Цену такси и экскурсии не называем: проверенного прайса в источниках этой страницы нет.</p>
<h2>Что делать, если проезд ограничили?</h2>
<p><strong>Разворачивайся. Объезд по грунту и чужим съездам — не план.</strong></p>
<p>День можно оставить в долине: <a href="/mesta/24">Хаджохская теснина</a> с оглядкой на лёд, смотровые <a href="/mesta/52">Гранитного каньона</a>, <a href="/mesta/48">Савранская канатка</a> только если она реально ходит. Ниже плато не значит «само по себе безопасно». Когда разворачиваться по колее и видимости — в статье <a href="/stati/posle-snegopada-kogda-razvorachivatsya">«После снегопада: когда разворачиваться»</a>.</p>
<p>Вернись с горной дороги засветло, даже если утром было открыто: к вечеру покрытие меняется. Если собираешь поездку целиком, смотри <a href="/stati/adygeya-v-dekabre">стоит ли ехать в декабре</a>, <a href="/stati/adygeya-zimoy-na-2-dnya">зимний план на два дня</a> и <a href="/stati/chto-vzyat-s-soboy-v-adygeyu">что взять с собой</a>.</p>
<p class="photo-credit"><small>Фото на обложке: Yana sss, <a href="https://creativecommons.org/licenses/by-sa/4.0/" rel="nofollow noopener" target="_blank">CC BY-SA 4.0</a>, <a href="https://commons.wikimedia.org/wiki/File:%22%D0%97%D0%B8%D0%BC%D0%B0_%D1%81%D0%BE%D0%B2%D1%81%D0%B5%D0%BC_%D0%B1%D0%BB%D0%B8%D0%B7%D0%BA%D0%BE%22_%D0%9F%D0%BB%D0%B0%D1%82%D0%BE_%D0%9B%D0%B0%D0%B3%D0%BE-%D0%9D%D0%B0%D0%BA%D0%B8.jpg" rel="nofollow noopener" target="_blank">Wikimedia Commons</a></small></p>$a14fb2$
     AND v_faq = $faq$[{"question":"Как доехать до Лаго-Наки зимой?","answer":"На машине со стороны Даховской. Асфальт не значит, что проедешь сегодня: смотри шины, сводки Госавтоинспекции и погоду на подъёме."},{"question":"Нужны ли зимние шины?","answer":"Для категорий M1 и N1 в декабре, январе и феврале эксплуатация без зимних шин на всех колёсах запрещена пунктом 5.2 перечня к постановлению Правительства № 1090. Это минимум по закону, не гарантия проезда."},{"question":"Открыта ли дорога на Лаго-Наки сейчас?","answer":"На этой странице текущего статуса нет. Ограничения появляются и снимаются. Пример 31 декабря 2025 года — прошлый сезон, не справка на сегодня."},{"question":"Можно ли доехать до Лаго-Наки без машины?","answer":"Подтверждённого рейса до КПП у нас нет. Не ставь плато обязательной точкой без машины, пока перевозчик не показал рейс на твой день."}]$faq$::jsonb
     AND v_feat = ARRAY[55,25,39,58,48,52]::integer[] THEN
    NULL; -- уже в целевом состоянии
  ELSIF v_title = $a14ft1$Лаго-Наки зимой на машине: дорога, КПП, ограничения$a14ft1$
     AND v_excerpt IS NOT DISTINCT FROM $a14fe1$Можно ли зимой доехать до КПП Лаго-Наки на легковушке: участки дороги Адыгея/край, шины, ограничения ГИБДД с датами и что делать, если закрыли.$a14fe1$
     AND v_body = $a14fb1$<p>На фото Лаго-Наки зимой — белые горы, хвойный лес и дорога среди снега. После таких кадров легко решить: «Да там же асфальт, доедем на обычной машине». Асфальт действительно есть. Но зимой решает не только покрытие — важнее, что на нём сейчас: сухо, снег, ледяная корка или перемёты.</p>
<p><strong>На легковушке доехать в сторону КПП бывает возможно.</strong> Но это не обещание проезда в любой зимний день. Иногда разумнее развернуться гораздо раньше, чем выяснять на подъёме, насколько хороши твои шины.</p>
<h2>Как устроена дорога</h2>
<p>Обычно поднимаются со стороны <strong>Даховской</strong>. По мере набора высоты погода может заметно меняться: внизу дождь, выше снег, а за очередным поворотом — туман. На маршруте встречаются смотровые и поворот к <a href="/mesta/25">Большой Азишской пещере</a>.</p>
<p>Путешествие проходит через территории <strong>Адыгеи и Краснодарского края</strong>. Большая Азишская пещера административно относится к Краснодарскому краю. Поэтому, когда читаешь сообщение «дорогу на Лаго-Наки ограничили», смотри, <strong>какой именно участок</strong> имеется в виду и кто опубликовал сообщение.</p>
<p>Перед подъёмом лучше заправиться, скачать карту для работы без связи и проверить прогноз на высоте. Не строй маршрут по времени, которое навигатор показал в сухую погоду: зимой дорога может занять больше, а остановки потребуют осторожности.</p>
<h2>Шины важнее уверенности за рулём</h2>
<p>Если наверху снег и гололёд, на машине с неподходящими шинами ехать не стоит. Заранее проверь состояние сезонной резины, тормозов, стеклоочистителей, омывателя и аккумулятора. Полный привод помогает трогаться в некоторых условиях, но <strong>не сокращает волшебным образом тормозной путь на льду</strong>.</p>
<p>Цепи противоскольжения могут быть полезны в определённых условиях, если они подходят автомобилю и используются по инструкции. Но это не пропуск через закрытую дорогу и не замена разумному решению отказаться от подъёма.</p>
<p>Если прогноз обещает метель, сильный снегопад или ледяной дождь — лучше сразу поменять план, чем проверять предел возможностей машины на горном участке.</p>
<h2>Дорога, КПП и заповедник — три разные вещи</h2>
<p>Здесь легко запутаться, поэтому разделим.</p>
<p><strong>Дорога</strong> — это подъезд в сторону Лаго-Наки. Её открытие или закрытие связано с дорожной обстановкой и ограничениями движения.</p>
<p><strong>КПП</strong> — контрольная точка Кавказского заповедника. Доехать до неё не означает автоматически получить право идти дальше: есть правила посещения, разрешённые маршруты и условия допуска.</p>
<p><strong>Тропы в заповеднике</strong> живут по собственному сезонному режиму. Например, по сообщению заповедника, опубликованному <strong>26 октября 2026 года</strong>, с <strong>27 октября</strong> варианты маршрута №30 В и Г были закрыты, а №30 А и Б оставлены лишь для <strong>однодневного посещения от КПП Лагонаки до Инструкторской щели, без ночёвки</strong>. Стоянки готовили к зиме.</p>
<p>И даже это объявление не доказывает, что путь до Инструкторской щели открыт именно в день твоей поездки. Уточняй актуальные сообщения и правила заповедника. Летнее описание большой «тридцатки» — не зимний план похода к Фишту.</p>
<h2>Где остановиться по пути</h2>
<p>На дороге есть <a href="/mesta/39">смотровая с качелями</a>. Но зимой это не обязательный выход из машины: снег может скрывать неровности, а лёд — делать подход опасным. Останавливайся только там, где разрешено и можно безопасно припарковаться.</p>
<figure class="shot"><img alt="Смотровая с качелями по дороге на Лаго-Наки" loading="lazy" src="https://hiotbrjgilwlztlfdkmg.supabase.co/storage/v1/object/public/uploads/542c3bb3b5e0432b9b225d659648e10d.webp"/><figcaption>Смотровая с качелями по дороге на Лаго-Наки</figcaption></figure>
<p><a href="/mesta/25">Большая Азишская пещера</a> тоже находится по пути. Если дорога и подход к объекту безопасны, а экскурсии проводятся, её можно рассмотреть как самостоятельную остановку. Заранее уточни часы и условия посещения: работа пещеры не следует автоматически из того, что к ней ведёт асфальт.</p>
<figure class="shot"><img alt="Большая Азишская пещера" loading="lazy" src="https://hiotbrjgilwlztlfdkmg.supabase.co/storage/v1/object/public/uploads/f6e131d6fccc471c9a4b3da7b9a8f39d.jpg"/><figcaption>Большая Азишская пещера</figcaption></figure>
<p>Не делай зимой обязательной целью <a href="/mesta/56">Каменное море</a> или выход на <a href="/mesta/58">Утюг</a>. Открытый край плато, наледь, ветер и плохая видимость — совсем не то же самое, что летняя прогулка по сухой тропе.</p>
<h2>Что делать, если проезд ограничили</h2>
<p><strong>Развернуться и не искать «секретный объезд».</strong> Грунтовки, нерасчищенные съезды и незнакомые лесные дороги могут быть опаснее основного маршрута. Если ограничение действует, его нужно соблюдать.</p>
<p>Можно остаться в долине Белой, остановиться на обед в Даховской или выбрать другой объект с подтверждённым доступом. <a href="/mesta/48">Канатная дорога</a> и смотровые <a href="/mesta/52">Гранитного каньона</a> — только после проверки погоды, работы и безопасности подходов. Они не становятся безопасными автоматически лишь потому, что находятся ниже плато.</p>
<p>Перед выездом проверь <strong>три разных источника информации</strong>: погоду в районе подъёма, официальные сообщения о дорожных ограничениях по нужному участку и свежие новости <a href="https://www.kavkazzapoved.ru/" rel="noopener" target="_blank">Кавказского заповедника</a>. Заложи возвращение с горной дороги <strong>засветло</strong>. Даже если всё открыто утром, к вечеру условия могут измениться.</p>
<p>Если хочешь провести в Адыгее выходные без гонки, смотри <a href="/stati/adygeya-zimoy-na-2-dnya">готовый зимний план на два дня</a> и <a href="/stati/chto-vzyat-s-soboy-v-adygeyu">что взять с собой</a>.</p>
<p class="photo-credit"><small>Фото на обложке: Yana sss, <a href="https://creativecommons.org/licenses/by-sa/4.0/" rel="nofollow noopener" target="_blank">CC BY-SA 4.0</a>, <a href="https://commons.wikimedia.org/wiki/File:%22%D0%97%D0%B8%D0%BC%D0%B0_%D1%81%D0%BE%D0%B2%D1%81%D0%B5%D0%BC_%D0%B1%D0%BB%D0%B8%D0%B7%D0%BA%D0%BE%22_%D0%9F%D0%BB%D0%B0%D1%82%D0%BE_%D0%9B%D0%B0%D0%B3%D0%BE-%D0%9D%D0%B0%D0%BA%D0%B8.jpg" rel="nofollow noopener" target="_blank">Wikimedia Commons</a></small></p>$a14fb1$
     AND v_faq = $faq$[]$faq$::jsonb
     AND v_feat = ARRAY[55,25,39,58,48,52]::integer[] THEN
    UPDATE articles
       SET title = $a14ft3$Как доехать до Лаго-Наки зимой$a14ft3$,
           excerpt = $a14fe3$До КПП «Лагонаки» зимой едут на машине со стороны Даховской, но асфальт не обещает проезд в конкретный день. Легковым машинам в декабре нужны зимние шины на всех колёсах; открыта ли дорога сегодня, смотри в сводках, не на этой странице.$a14fe3$,
           body = $a14fb3$<p><strong>Зимой до КПП «Лагонаки» едут на машине со стороны Даховской. Доехать «в любой день и на любой резине» нельзя.</strong> Асфальт на этом направлении есть. Открыт ли он сегодня, эта страница не знает и проезд не гарантирует: решают шины, то, что лежит на покрытии, и нет ли ограничения движения.</p>
<p>Снег на хребте и проезд — разные новости. Про снег — <a href="/stati/pervyy-sneg-na-lago-naki-ehat-ili-net">отдельная страница</a>. Здесь только дорога.</p>
<h2>Как доехать до КПП зимой?</h2>
<p><strong>Обычный заезд — из долины через Даховскую, дальше серпантин в сторону КПП.</strong> Участок идёт и по Адыгее, и по Краснодарскому краю, поэтому фраза «дорогу на Лаго-Наки закрыли» без названия участка и без того, кто её опубликовал, ещё ничего не значит. <a href="/mesta/25">Большая Азишская пещера</a> административно в крае, не в Адыгее.</p>
<p>По мере набора высоты погода меняется: внизу дождь, выше снег или туман. Заправься в Каменномостском или в Даховской до начала подъёма. Скачай карту для работы без связи. Время, которое навигатор показал в сухую погоду, зимой не план.</p>
<h2>Какие шины требует закон и чего он не гарантирует?</h2>
<p><strong>В декабре, январе и феврале легковой машине нужны зимние шины на всех колёсах. Это запрет эксплуатации, а не обещание, что дорога будет проезжей.</strong></p>
<p>Пункт 5.2 Перечня неисправностей и условий, при которых запрещается эксплуатация транспортных средств (приложение к Основным положениям, постановление Правительства РФ от 23.10.1993 № 1090), называет два условия: на транспортном средстве категорий M1 и N1 не установлены зимние шины в зимний период (декабрь, январь, февраль); зимние шины установлены не на все колёса. Для обычной легковой машины это как раз этот пункт. Текст сверен по карточке <a href="https://www.consultant.ru/document/cons_doc_LAW_2709/ec034e2d80085428905b10189ee7d0d08173e8c7/" rel="nofollow noopener" target="_blank">КонсультантПлюс</a>, где у документа указана редакция от 28.08.2026. Сумму штрафа здесь не приводим.</p>
<p>Этого минимума мало для серпантина. Перечень не обещает, что зимняя шина проедет перемёт, колею или ледяную корку, и не обязывает держать участок открытым. Полный привод помогает тронуться в части условий, не заменяет шины и не сокращает тормозной путь на льду.</p>
<h3>Нужны ли цепи на легковой?</h3>
<p><strong>Пункт 5.2 для категории M1 цепи не требует.</strong> Цепи, если они подходят машине и ты умеешь их ставить, — снаряжение на конкретный участок. Они не заменяют зимние шины и не дают права ехать через закрытие. Отдельное требование возить цепи зимой в этом перечне относится к другим категориям транспорта, не к обычной легковушке.</p>
<p>Остаточная глубина протектора зимней шины — пункт 5.5 того же перечня: 4 мм и менее на обледеневшем или заснеженном покрытии. Выявляют это средствами диагностики, а не линейкой на обочине. Это не самопроверка перед шлагбаумом.</p>
<h2>Открыта ли дорога сегодня?</h2>
<p><strong>Текущего статуса здесь нет.</strong> Ограничение могут ввести утром и снять днём. Мы не пишем ни «сегодня открыто», ни «сегодня закрыто».</p>
<p>Пример, что так уже бывало, а не прогноз: 31 декабря 2025 года Госавтоинспекция Краснодарского края сообщала о временном ограничении движения на автодороге «станица Даховская — плато Лаго-Наки» из-за снега. Так это передал <a href="https://ria.ru/20251231/kuban-2065884978.html" rel="nofollow noopener" target="_blank">РИА Новости</a>. Это прошлый сезон. Когда ограничение сняли и сняли ли его в тот же вечер, здесь не утверждаем.</p>
<p>Перед выездом смотри сообщения по обоим регионам: дорога их пересекает. Раздел Краснодарского края — <a href="https://xn--90adear.xn--p1ai/r/23/" rel="nofollow noopener" target="_blank">гибдд.рф/r/23</a>, раздел Адыгеи — <a href="https://xn--90adear.xn--p1ai/r/01/" rel="nofollow noopener" target="_blank">гибдд.рф/r/01</a>. Статья эти страницы не зеркалирует. Если сайт не открылся, не заменяй его пересказом из чата. Ограничение на месте обозначают и экипажи: объезжать его по обочине нельзя.</p>
<h2>Чем дорога отличается от КПП и троп?</h2>
<p><strong>Доехать до шлагбаума, пройти КПП и идти по летней тропе — три разных разрешения.</strong></p>
<p>Дорога — это проезд в сторону <a href="/mesta/55">Лаго-Наки</a>. Её открывают и ограничивают по обстановке.</p>
<p>КПП — контроль Кавказского заповедника. Машина у шлагбаума не означает, что дальше можно идти: есть правила посещения и сезонный режим маршрутов.</p>
<p>По сообщению заповедника от 26 октября 2026 года, с 27 октября маршруты №30 В и Г закрыты, а №30 А и Б со стороны КПП «Лагонаки» оставлены для однодневного выхода до Инструкторской щели, без ночёвки. Это не справка на день поездки: более позднее объявление отменяет старое. Смотри <a href="https://www.kavkazzapoved.ru/" rel="nofollow noopener" target="_blank">kavkazzapoved.ru</a>. Летнее описание «тридцатки» — не зимний план к Фишту.</p>
<h2>Где можно остановиться по пути?</h2>
<p><strong>Отдельной проверенной схемы парковок мы не публикуем.</strong> Останавливайся только там, где это разрешено и машина не стоит в полосе. Зимой не выходи «на кадр», если подход не виден из-под снега или льда.</p>
<p>На дороге есть <a href="/mesta/39">смотровая с качелями</a>. Это не обязательная остановка: лёд на подходе важнее качелей.</p>
<figure class="shot"><img alt="Смотровая с качелями по дороге на Лаго-Наки" loading="lazy" src="https://hiotbrjgilwlztlfdkmg.supabase.co/storage/v1/object/public/uploads/542c3bb3b5e0432b9b225d659648e10d.webp"/><figcaption>Смотровая с качелями по дороге на Лаго-Наки</figcaption></figure>
<p><a href="/mesta/25">Большая Азишская пещера</a> тоже по пути. Имеет смысл, если и дорога, и подход безопасны и экскурсия в этот день идёт. Часы сами из того, что к пещере ведёт асфальт, не следуют — уточни на месте.</p>
<figure class="shot"><img alt="Большая Азишская пещера" loading="lazy" src="https://hiotbrjgilwlztlfdkmg.supabase.co/storage/v1/object/public/uploads/f6e131d6fccc471c9a4b3da7b9a8f39d.jpg"/><figcaption>Большая Азишская пещера</figcaption></figure>
<p>Не ставь зимой целью <a href="/mesta/56">Каменное море</a> или выход на <a href="/mesta/58">Утюг</a>. Край плато, наледь и ветер — не летняя прогулка по сухой тропе.</p>
<h2>Как быть без машины?</h2>
<p><strong>Подтверждённого рейса до КПП «Лагонаки» у нас нет.</strong> Автобусы до Каменномостского, Даховской и Гузерипля, о которых написано в других материалах сайта, сами по себе до плато не доезжают. Пока перевозчик не показал рейс на твой день, не закладывай Лаго-Наки в поездку без машины. Цену такси и экскурсии не называем: проверенного прайса в источниках этой страницы нет.</p>
<h2>Что делать, если проезд ограничили?</h2>
<p><strong>Разворачивайся. Объезд по грунту и чужим съездам — не план.</strong></p>
<p>День можно оставить в долине: <a href="/mesta/24">Хаджохская теснина</a> с оглядкой на лёд, смотровые <a href="/mesta/52">Гранитного каньона</a>, <a href="/mesta/48">Савранская канатка</a> только если она реально ходит. Ниже плато не значит «само по себе безопасно». Когда разворачиваться по колее и видимости — в статье <a href="/stati/posle-snegopada-kogda-razvorachivatsya">«После снегопада: когда разворачиваться»</a>.</p>
<p>Вернись с горной дороги засветло, даже если утром было открыто: к вечеру покрытие меняется. Если собираешь поездку целиком, смотри <a href="/stati/adygeya-v-dekabre">стоит ли ехать в декабре</a>, <a href="/stati/adygeya-zimoy-na-2-dnya">зимний план на два дня</a> и <a href="/stati/chto-vzyat-s-soboy-v-adygeyu">что взять с собой</a>.</p>
<p class="photo-credit"><small>Фото на обложке: Yana sss, <a href="https://creativecommons.org/licenses/by-sa/4.0/" rel="nofollow noopener" target="_blank">CC BY-SA 4.0</a>, <a href="https://commons.wikimedia.org/wiki/File:%22%D0%97%D0%B8%D0%BC%D0%B0_%D1%81%D0%BE%D0%B2%D1%81%D0%B5%D0%BC_%D0%B1%D0%BB%D0%B8%D0%B7%D0%BA%D0%BE%22_%D0%9F%D0%BB%D0%B0%D1%82%D0%BE_%D0%9B%D0%B0%D0%B3%D0%BE-%D0%9D%D0%B0%D0%BA%D0%B8.jpg" rel="nofollow noopener" target="_blank">Wikimedia Commons</a></small></p>$a14fb3$,
           faq = $faq$[{"question":"Как доехать до Лаго-Наки зимой?","answer":"На машине со стороны Даховской. Асфальт не значит, что проедешь сегодня: смотри шины, сводки Госавтоинспекции и погоду на подъёме."},{"question":"Нужны ли зимние шины?","answer":"Для категорий M1 и N1 в декабре, январе и феврале эксплуатация без зимних шин на всех колёсах запрещена пунктом 5.2 перечня к постановлению Правительства № 1090. Это минимум по закону, не гарантия проезда."},{"question":"Открыта ли дорога на Лаго-Наки сейчас?","answer":"На этой странице текущего статуса нет. Ограничения появляются и снимаются. Пример 31 декабря 2025 года — прошлый сезон, не справка на сегодня."},{"question":"Можно ли доехать до Лаго-Наки без машины?","answer":"Подтверждённого рейса до КПП у нас нет. Не ставь плато обязательной точкой без машины, пока перевозчик не показал рейс на твой день."}]$faq$::jsonb,
           featured_checkpoint_ids = ARRAY[55,25,39,58,48,52]::integer[],
           updated_at = now()
     WHERE id = 14
       AND slug = 'lago-naki-zimoy-na-mashine'
       AND is_published IS TRUE;
    GET DIAGNOSTICS v_n = ROW_COUNT;
