      RAISE EXCEPTION 'article 14: обновлена не одна строка (%)', v_n;
    END IF;
  ELSE
    RAISE EXCEPTION 'article 14 (lago-naki-zimoy-na-mashine) не совпал ни со снимком «до», ни с целевым текстом — строку не трогаем';
  END IF;
  IF (SELECT cover_url FROM articles WHERE id = 14) IS DISTINCT FROM v_cover
     OR (SELECT slug FROM articles WHERE id = 14) IS DISTINCT FROM 'lago-naki-zimoy-na-mashine'
     OR (SELECT is_published FROM articles WHERE id = 14) IS DISTINCT FROM TRUE
     OR (SELECT featured_trail_ids FROM articles WHERE id = 14) IS DISTINCT FROM v_trails
     OR (SELECT position('Как доехать до КПП зимой?' IN body) FROM articles WHERE id = 14) = 0 THEN
