  -- article 15 pervyy-sneg-na-lago-naki-ehat-ili-net
  SELECT title, excerpt, body, faq, featured_checkpoint_ids, cover_url, slug, is_published, featured_trail_ids
    INTO v_title, v_excerpt, v_body, v_faq, v_feat, v_cover, v_slug, v_pub, v_trails
