  IF NOT FOUND THEN
    RAISE EXCEPTION 'article 15 (pervyy-sneg-na-lago-naki-ehat-ili-net) не найден';
  END IF;
  IF v_slug IS DISTINCT FROM 'pervyy-sneg-na-lago-naki-ehat-ili-net' OR v_pub IS DISTINCT FROM TRUE THEN
